#define DF_SAT_CHK(T, NAME, LO, HI) \
  static T df_satc_##NAME##_i(int64_t v) { \
    T r = df_sat_##NAME##_i(v); \
    if ((int64_t)r != v) df_silent_note(&df_desc_OutOfRangeCastException); \
